+int main(int argc, char **argv) {
+    BEGIN_TEST();
+    {
+        /* Test generate ephemeral keys for all supported curves */
+        for (int i = 0; i < s2n_ecc_evp_supported_curves_list_len; i++) {
+            struct s2n_ecc_evp_params evp_params = {0};
