     public CoordinatorService(
             @NonNull NodeEngineImpl nodeEngine,
             @NonNull SeaTunnelServer seaTunnelServer,
             EngineConfig engineConfig) {
        this.dynamicSlot = engineConfig.getSlotServiceConfig().isDynamicSlot();
         this.nodeEngine = nodeEngine;
         this.logger = nodeEngine.getLogger(getClass());
         this.executorService =
                new ThreadPoolExecutor(
                        0,
                        Integer.MAX_VALUE,
                        60L,
                        TimeUnit.SECONDS,
                        new SynchronousQueue<>(),
                        new ThreadFactoryBuilder()
                                .setNameFormat("seatunnel-coordinator-service-%d")
                                .build(),
                         new ThreadPoolStatus.RejectionCountingHandler());
         this.seaTunnelServer = seaTunnelServer;
         this.engineConfig = engineConfig;
         masterActiveListener = Executors.newSingleThreadScheduledExecutor();
         masterActiveListener.scheduleAtFixedRate(
                 this::checkNewActiveMaster, 0, 100, TimeUnit.MILLISECONDS);
         isJobPending = engineConfig.getScheduleStrategy().equals(ScheduleStrategy.WAIT);
        if (!dynamicSlot && isJobPending) {
             logger.info("Start pending job schedule thread");
             // start pending job schedule thread
             startPendingJobScheduleThread();
         }
     }

    private void startPendingJobScheduleThread() {
        Runnable pendingJobScheduleTask =
                () -> {
                    Thread.currentThread().setName("pending-job-schedule-runner");
                    while (true) {
                        try {
                            // sleep 5s , not too frequent
                            Thread.sleep(5000);
                        } catch (InterruptedException e) {
                            throw new RuntimeException(e);
                        }
                        pendingJobSchedule();
                    }
                };
         new Thread(pendingJobScheduleTask).start();
     }

     private void pendingJobSchedule() {
         pendingJob.stream()
                 .findFirst()
                .ifPresent(
                         pendingJobEntry -> {
                             Long jobId = pendingJobEntry._1;
                             JobMaster jobMaster = pendingJobEntry._2;

                             logger.info(
                                     "Start calculating whether pending task resources are enough: "
                                             + jobId);

                            if (jobMaster.preApplyResources()) {
                                 logger.info("Resources enough, start running: " + jobId);
                                 pendingJob.pollFirst();
                                 PendingSourceState pendingSourceState =
                                         pendingJobMasterMap.get(jobId)._1;

                                 CompletableFuture.runAsync(
                                         () -> {
                                             try {
                                                if (pendingSourceState
                                                        == PendingSourceState.RESTORE) {
                                                    jobMaster
                                                            .getPhysicalPlan()
                                                            .getPipelineList()
                                                            .forEach(SubPlan::restorePipelineState);
                                                }
                                                pendingJobMasterMap.remove(jobId);
                                                 runningJobMasterMap.put(jobId, jobMaster);
                                                 jobMaster.run();
                                             } finally {
                                                if (jobMasterCompletedSuccessfully(
                                                        jobMaster, pendingSourceState)) {
                                                     runningJobMasterMap.remove(jobId);
                                                 }
                                             }
                                        },
                                        executorService);
                            } else {
                                logger.info("Resources not enough, waiting next time");
                            }
                         });
     }

    private boolean jobMasterCompletedSuccessfully(JobMaster jobMaster, PendingSourceState state) {
        return (!jobMaster.getJobMasterCompleteFuture().isCompletedExceptionally()
                        && state == PendingSourceState.RESTORE)
                || (!jobMaster.getJobMasterCompleteFuture().isCancelled()
                        && state == PendingSourceState.SUBMIT);
    }

     private JobEventProcessor createJobEventProcessor(
             String reportHttpEndpoint,
