void Song::getActiveModControllable(ModelStackWithTimelineCounter* modelStack) {
	if (affectEntire) {
		modelStack->setTimelineCounter(this);
		modelStack->addOtherTwoThingsButNoNoteRow(&globalEffectable, &paramManager);
	}
	else {
